# 양면 인쇄용 카드 배치: 카드 사이 틈 G, 바깥 여백(블리드) BX·BY를 색으로 채워
# 뒷면이 밀려도 앞면 점선대로 자르면 흰 종이가 안 보이게 한다. 점선은 앞면에만.
def cut_css_js(color, Z=.93, G=0, BX=4, BY=6, BS=.9):
    # BS: 뒷면 카드를 칸 안에서 줄이는 비율 → 둘레에 색 테두리(밀려도 흰색·옆 카드가 안 보이게)
    W = round(70*Z, 2); H = round(99*Z, 2)
    GW = 3*W + 2*G; GH = 3*H + 2*G; L0 = (210-GW)/2; T0 = (297-GH)/2
    css = f'''<style>.sheet{{display:grid!important;grid-template-columns:repeat(3,{W}mm)!important;grid-auto-rows:{H}mm!important;gap:{G}mm!important;width:210mm!important;height:297mm!important;box-sizing:border-box!important;padding:{T0:.2f}mm 0 0 0!important;justify-content:center!important;align-content:start!important;position:relative}}
.sheet>.card{{zoom:{Z};outline:none!important;position:relative;z-index:1}}.sheet>.bleed{{position:absolute;z-index:0;background:{color}}}.sheet>.card.bk2{{zoom:{Z*BS:.4f}!important;justify-self:center;align-self:center}}.cut{{position:absolute;z-index:50;pointer-events:none}}.cut.v{{width:0;border-left:.3mm dashed #999}}.cut.h{{height:0;border-top:.3mm dashed #999}}</style>'''
    js = f'''<script>for(const s of document.querySelectorAll('.sheet')){{if(!s.querySelector('.card'))continue;const G={G};const back=!!s.querySelector('.bk2');const kids=[...s.children];if(back)kids.forEach((k,i)=>{{if(!k.classList.contains('card'))return;const c=i%3,r=Math.floor(i/3);const b=document.createElement('div');b.className='bleed';const ex=G/2+(c==0?{BX}:3),ex2=G/2+(c==2?{BX}:3),ey=G/2+(r==0?{BY}:3),ey2=G/2+(r==2?{BY}:3);const x={L0:.3f}+c*({W}+G),y={T0:.3f}+r*({H}+G);b.style.cssText=`left:${{x-ex}}mm;top:${{y-ey}}mm;width:${{{W}+ex+ex2}}mm;height:${{{H}+ey+ey2}}mm`;s.prepend(b)}});if(back)continue;const W={W},H={H},L={L0:.3f},T={T0:.3f};const xs=[L-G/2,L+W+G/2,L+2*W+1.5*G,L+3*W+2.5*G],ys=[T-G/2,T+H+G/2,T+2*H+1.5*G,T+3*H+2.5*G];for(const x of xs){{const d=document.createElement('div');d.className='cut v';d.style.cssText=`left:${{x}}mm;top:${{ys[0]-{BY+3}}}mm;height:${{ys[3]-ys[0]+{2*BY+6}}}mm`;s.appendChild(d)}}for(const y of ys){{const d=document.createElement('div');d.className='cut h';d.style.cssText=`top:${{y}}mm;left:${{xs[0]-{BX+1.5}}}mm;width:${{xs[3]-xs[0]+{2*BX+3}}}mm`;s.appendChild(d)}}}}</script>'''
    return css, js
